@pytest.mark.obl("S1-013a")
def test_reset_100_users_under_10s(api):
    fx = fixture(users=[user(f"u_{i}", f"h{i}", 1) for i in range(100)], payments=[], requests=[],
                 settlement_operator_ids=[])
    t0 = time.monotonic()
    api.reset(fx)
